{
  "findings": [
    {
      "check_id": "CKV_AWS_23",
      "title": "Ensure every security group and rule has a description",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "The security group rule lacks a description, which makes it harder to understand its purpose and manage it effectively."
    },
    {
      "check_id": "CKV_AWS_25",
      "title": "Ensure no security groups allow ingress from 0.0.0.0:0 to port 3389",
      "resource": "aws_security_group_rule.changeme_remote_exec_inline_security_group_rule_incoming_rdp",
      "severity": "MEDIUM",
      "explanation": "Allowing ingress from 0.0.0.0/0 to port 3389 (RDP) exposes the resource to the entire internet, increasing the risk of unauthorized access."
    }
  ],
  "patched_code": "resource \"aws_security_group_rule\" \"changeme_remote_exec_inline_security_group_rule_incoming_rdp\" {\n  security_group_id = aws_security_group.changeme_remote_exec_inline_windows_security_group.id\n  type              = \"ingress\"\n  from_port         = 3389\n  to_port           = 3389\n  protocol          = \"tcp\"\n  cidr_blocks       = [\"192.168.0.0/16\"]\n  description       = \"Allow RDP access from internal network\"\n}",
  "fix_summary": "Added a description to the security group rule for better clarity and restricted ingress to a private CIDR range (192.168.0.0/16) instead of 0.0.0.0/0 to mitigate exposure to the internet."
}
